contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(true);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 oppositeHash = c.hashOppositeOrder(order);
        bytes32 orderHash = c.hashOrder(order);

        order.isLong = !order.isLong;
        bytes32 recomputedHash = c.hashOrder(order);

        assert(oppositeHash == recomputedHash && oppositeHash != orderHash);
    }

    receive() external payable {}
}

