contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        bytes calldata signature,
        uint256[] calldata floorAssetTokenIds
    ) public payable {
        require(maker != address(0));
        require(baseAsset != address(0));
        require(expiration > block.timestamp);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bool firstAttemptReverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256) {
            firstAttemptReverted = false;
        } catch {
            firstAttemptReverted = true;
        }

        bytes32 orderHash = c.hashOrder(order);
        uint256 positionId = uint256(orderHash);

        bool secondAttemptReverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) returns (uint256) {
            secondAttemptReverted = false;
        } catch {
            secondAttemptReverted = true;
        }

        if (!firstAttemptReverted) {
            assert(c.ownerOf(positionId) == maker);
        }
        assert(secondAttemptReverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(maker != address(0));
        require(maker != address(this));
        require(baseAsset != address(0));
        require(expiration > block.timestamp);
        require(duration > 0);
        require(duration < 10_000 days);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        c.setBaseURI("");
        c.setFee(0);

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeOrderHash = c.hashOppositeOrder(order);
        uint256 longPositionId = uint256(orderHash);
        uint256 shortPositionId = uint256(oppositeOrderHash);

        uint256 beforeTimestamp = block.timestamp;

        bool reverted;
        try c.fillOrder(order, hex"", new uint256[](0)) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            if (order.isLong) {
                assert(c.ownerOf(longPositionId) == maker);
            } else {
                assert(c.ownerOf(shortPositionId) == maker);
            }

            uint256 expectedExpiration = beforeTimestamp + order.duration;
            assert(c.positionExpirations(longPositionId) == expectedExpiration);
        }
    }
}

contract InvMutTest {
