        });

        c.setBaseURI("");
        c.setFee(0);

        bytes32 orderHash = c.hashOrder(order);
        uint256 longPositionId = uint256(orderHash);

        bool fillReverted;
        uint256 beforeTimestamp = block.timestamp;
        try c.fillOrder(order, hex"", new uint256[](0)) returns (uint256) {
            fillReverted = false;
        } catch {
            fillReverted = true;
        }

        bool stillBeforeExpiration = block.timestamp <= c.positionExpirations(longPositionId);

