contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256 amount
    ) public payable {
        // 1% fee -> feeAmount = premium / 100, computable purely from parameters,
        // so no state-changing call is needed to determine whether fee > 0.
        uint256 expectedFee = premium / 100;
        require(expectedFee == 0);
        uint256 payment = premium;

        require(address(this).balance >= amount);
        require(amount >= 1);
        require(uint256(uint160(address(c))) != 0);
        require(amount != uint256(uint160(address(c))));
        require(amount != strike);
        require(strike != premium);
        require(premium != 0);
        require(duration > 0);
        require(duration < 10_000 days);
        require(expiration > block.timestamp);

        // Setup calls, all top-level.
        c.setBaseURI("ipfs://putty/");
        c.setFee(1_000_000);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: address(0),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);
        uint256 posId = uint256(orderHash);

        // Reaching this call requires the fees to be zero, otherwise it reverts:
        // the path would need baseAsset to be a contract and transferFrom to succeed.
        c.fillOrder{value: amount}(order, hex"", new uint256[](0));

        require(uint256(uint160(address(c))) != 0);
	    // First fillOrder minted both position tokens; the maker owns posId.
        (bool withdrawSucceeded, ) = address(c).call(abi.encodeWithSignature("withdraw((address,bool,bool,address,uint256,uint256,uint256,uint256,uint256,address[],address[],(address,uint256)[],(address,uint256)[]))", order));
        require(uint256(uint160(address(c))) != 0);

        bool withdrew = withdrawSucceeded;

        c.withdraw(order);

        bool ownerIsDead = (c.ownerOf(posId) == address(0xdead));
        bool positionExpired = (block.timestamp > c.positionExpirations(posId));

        // General rule: if the short position could be filled (fee was zero),
        // and the position is not past its expiration, the maker must have been
        // able to withdraw exactly once and be able to withdraw a second time
        // only if the position had already expired.
        assert(withdrew && (!positionExpired || ownerIsDead));
    }

    receive() external payable {}
}

