contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        address erc721AssetToken,
        uint256 erc721AssetTokenId,
        uint256 strike,
        uint256 premium,
        uint256 nonce,
        uint256 ethAmount
    ) public payable {
        // This rule is about exercise of a long *call* on a weth baseAsset:
        // exercise must consume exactly `strike` wei as msg.value, no more, no less.
        // Anything else must revert (no Ether is forwarded into the position).
        // We use a simple long call order with no erc20/erc721 assets granted to the exercise.

        C.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = c.weth();
        order.strike = strike;
        order.premium = premium;
        order.duration = 1 days;
        order.expiration = block.timestamp + 1 days;
        order.nonce = nonce;
        // leave whitelist/floorTokens/erc20Assets/erc721Assets empty

        bytes32 orderHash = c.hashOrder(order);
        uint256 positionId = uint256(orderHash);

        // The test contract is the maker/filler so it owns the long position after fillOrder.
        // Give this test contract enough weth to pay the premium and enough ether for strike.
        // A real weth baseAsset requires msg.value == premium when filling as the long side.
        // We fill via msg.value path only if baseAsset == weth; otherwise ERC20 transferFrom is needed.
        // To keep the rule deterministic and reachable, require the caller supplies enough Ether.
        require(address(this).balance >= strike, "not enough balance for strike");

        // Fill the order. Since baseAsset is weth and we are the long side, msg.value must equal premium.
        // The test contract is the maker and the filler, so the premium Ether flows between the same address
        // (plus fee), netting out to nothing relevant for the exercise rule.
        // We pass the premium as the value parameter to the fill call.
        c.fillOrder{value: premium}(order, "", new uint256[](0));

        // Sanity precondition: the caller truly owns the long position and it has not expired.
        require(c.ownerOf(positionId) == address(this), "did not get long position");
        require(block.timestamp < c.positionExpirations(positionId), "position expired");

        // The deciding call: exercise the long call with an arbitrary ethAmount supplied by the caller.
        bool reverted;
        try c.exercise{value: ethAmount}(order, new uint256[](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: this long call exercise succeeds exactly when the Ether sent equals the strike.
        assert(reverted == (ethAmount != strike));
    }

    receive() external payable {}
}

