contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(C.Order memory order) public payable {
        // Only meaningful when the test contract is not the maker.
        require(order.maker != address(this));

        // Read the cancellation flag before the call.
        bytes32 h = c.hashOrder(order);
        bool before = c.cancelledOrders(h);

        // The deciding call: attempt to cancel an order we did not make.
        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, the sender must have been the maker (contradiction),
        // otherwise the flag must have changed from false to true.
        bytes32 h2 = c.hashOrder(order);
        bool after = c.cancelledOrders(h2);

        assert(reverted || (order.maker == address(this) && !before && after));
    }

    receive() external payable {}
}

